/bin/bash -lc "python3 - <<'PY'
import urllib.request, concurrent.futures
base='https://raw.githubusercontent.com/NVIDIA/cuda-samples/db3eea23946bca2e90a75eca2b5b3e07158a9e11/'
paths=['Samples/5_Domain_Specific/MonteCarloMultiGPU/MonteCarloMultiGPU.cpp','Samples/5_Domain_Specific/MonteCarloMultiGPU/MonteCarlo_kernel.cu','Samples/5_Domain_Specific/MonteCarloMultiGPU/CMakeLists.txt','Samples/5_Domain_Specific/MonteCarloMultiGPU/MonteCarlo_common.h']
def get(p):
 try:
  s=urllib.request.urlopen(base+p,timeout=25).read().decode()
  return p+'\\n'+s
 except Exception as e:return p+' '+str(e)
for s in concurrent.futures.ThreadPoolExecutor().map(get,paths):print(s)
PY"

